const { native } = require('./config/_import.js')
const { logDir } = require('./config/log_dir.js')
const { conOptions } = require('./config/connection_options.js')

const path = require('path')
const logfilename = __filename.split(path.sep).pop().replace('.js', '.log')
conOptions.logfile = path.join(logDir, logfilename)

let connection
try {
  connection = native.createConnection(conOptions)
  const iris = connection.createIris()
  const pop = 'Iñtërnâtiônàlizætiøn☃💩'
  iris.set(pop, 'isc.iris.string', 1)
  iris.set('Καλημέρα κόσμε!!!', 'isc.iris.string', 2)
  iris.set('mirëmëngjes', 'isc.iris.string', 3)
  iris.set('доброе утро', 'isc.iris.string', 4)
  iris.set('صباح الخير', 'isc.iris.string', 5)
  iris.set('בוקר טוב', 'isc.iris.string', 6)
  iris.set('สวัสดีตอนเช้า', 'isc.iris.string', 7)
  iris.set('roj baş', 'isc.iris.string', 8)

  console.log(iris.get('isc.iris.string', 3)) // getString
  connection.close()
} catch (err) {
  console.log(err)
  if (connection) {
    connection.close()
  }
}
